<script setup lang="ts">
// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Download the encrypted database file for backup (nothing is decrypted here).

import axios from '@nextcloud/axios';
import { t } from '@nextcloud/l10n';
import { generateUrl } from '@nextcloud/router';

async function exportCopy(): Promise<void> {
  const response = await axios.get(generateUrl('/apps/upm/db'), { responseType: 'blob' });
  const url = URL.createObjectURL(response.data as Blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'upm.db';
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}
</script>

<template>
  <button type="button" class="button" @click="exportCopy">
    {{ t('upm', 'Export encrypted copy') }}
  </button>
</template>
